import { mkdir, readFile, rm, writeFile } from 'node:fs/promises';
import { dirname, join, resolve, sep } from 'node:path';
import { signToken, verifyToken } from './signing';

/** Object keys are generated by the server only; anything else is rejected before touching the disk. */
const KEY_PATTERN = /^[a-z0-9-]+(\/[a-z0-9-]+)*\.(jpg)$/;

type UploadClaims = { kind: 'upload'; imageId: string; ownerId: string; exp: number };
type ReadClaims = { kind: 'read'; key: string; exp: number };

export type SignedUrl = { url: string; expiresAt: Date };

/**
 * Private object storage on the local disk, used in development until the S3-compatible adapter exists.
 * Mirrors the S3 model: files are never public; uploads and reads go through short-lived signed URLs
 * (served by this API's `/v1/uploads/:token` and `/v1/files/:token` routes).
 */
export function createLocalDiskStorage({ rootDir, secret }: { rootDir: string; secret: string }) {
  const root = resolve(rootDir);

  const pathFor = (key: string) => {
    if (!KEY_PATTERN.test(key)) throw new Error(`Invalid storage key: ${key}`);
    const path = resolve(join(root, key));
    if (!path.startsWith(root + sep)) throw new Error(`Storage key escapes root: ${key}`);
    return path;
  };

  return {
    async put(key: string, data: Buffer): Promise<void> {
      const path = pathFor(key);
      await mkdir(dirname(path), { recursive: true });
      await writeFile(path, data);
    },

    async read(key: string): Promise<Buffer | null> {
      try {
        return await readFile(pathFor(key));
      } catch (error) {
        if ((error as NodeJS.ErrnoException).code === 'ENOENT') return null;
        throw error;
      }
    },

    async delete(keys: readonly string[]): Promise<void> {
      await Promise.all(keys.map((key) => rm(pathFor(key), { force: true })));
    },

    createUploadUrl(claims: { imageId: string; ownerId: string }, origin: string, ttlMs: number): SignedUrl {
      const exp = Date.now() + ttlMs;
      const token = signToken({ kind: 'upload', ...claims, exp } satisfies UploadClaims, secret);
      return { url: `${origin}/v1/uploads/${token}`, expiresAt: new Date(exp) };
    },

    verifyUploadToken(token: string): UploadClaims | null {
      const claims = verifyToken<UploadClaims>(token, secret);
      return claims?.kind === 'upload' ? claims : null;
    },

    createReadUrl(key: string, origin: string, ttlMs: number): SignedUrl {
      const exp = Date.now() + ttlMs;
      const token = signToken({ kind: 'read', key, exp } satisfies ReadClaims, secret);
      return { url: `${origin}/v1/files/${token}`, expiresAt: new Date(exp) };
    },

    verifyReadToken(token: string): ReadClaims | null {
      const claims = verifyToken<ReadClaims>(token, secret);
      return claims?.kind === 'read' ? claims : null;
    },
  };
}

export type ObjectStorage = ReturnType<typeof createLocalDiskStorage>;
